// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {EwaldKernelBase} from "./EwaldKernelBase.sol";
import {FloatMath} from "../math/FloatMath.sol";

/// @notice Tin-foil Ewald self, neutralizing-background and pair-exception terms.
contract EwaldCorrections is EwaldKernelBase {
    bytes32 public constant KERNEL_ID =
        keccak256("ORVIA.EwaldCorrections.v0.5");
    bytes16 private constant HALF = 0x3ffe0000000000000000000000000000;
    struct ExceptionParameters {
        bytes16 original;
        bytes16 desired;
        bytes16 prefactor;
        bytes16 alpha;
    }

    constructor(
        address math_,
        address scalar_
    ) EwaldKernelBase(math_, scalar_) {}

    function selfEnergy(
        bytes16 charge,
        bytes16 alpha,
        bytes16 prefactor
    ) external view returns (bytes16) {
        _finite(charge);
        _positive(alpha);
        _nonnegative(prefactor);
        FloatMath m = numericalMath;
        bytes16 result = m.mul(charge, charge);
        result = m.mul(result, INV_SQRT_PI);
        result = m.mul(result, alpha);
        result = m.neg(m.mul(result, prefactor));
        _finite(result);
        return result;
    }

    /// @notice Uniform neutralizing plasma: -K*pi*Q^2/(2*alpha^2*V).
    /// @dev Zero coordinate force at fixed volume; pressure derivatives are not returned.
    function backgroundEnergy(
        bytes16 totalCharge,
        bytes16[3] calldata box,
        bytes16 alpha,
        bytes16 prefactor
    ) external view returns (bytes16) {
        _finite(totalCharge);
        _positive(alpha);
        _nonnegative(prefactor);
        FloatMath m = numericalMath;
        bytes16 denominator = m.mul(alpha, alpha);
        denominator = m.mul(denominator, _volume(box));
        denominator = m.mul(TWO, denominator);
        bytes16 numerator = m.mul(totalCharge, totalCharge);
        numerator = m.mul(numerator, PI);
        numerator = m.mul(numerator, prefactor);
        bytes16 result = m.neg(m.div(numerator, denominator));
        _finite(result);
        return result;
    }

    /// @notice K*(desiredQ-originalQ*erf(alpha*r))/r, replacing an omitted real pair.
    /// @dev Reciprocal factors retain original atomic charges. Caller must omit this
    ///      pair's screened real term, then add this term once with no cutoff.
    function exception(
        bytes16[3] calldata displacement,
        bytes16 originalChargeProduct,
        bytes16 desiredChargeProduct,
        bytes16 prefactor,
        bytes16 alpha
    ) external view returns (bytes16 energy, bytes16[3] memory forceOnA) {
        return
            _exception(
                displacement,
                ExceptionParameters(
                    originalChargeProduct,
                    desiredChargeProduct,
                    prefactor,
                    alpha
                )
            );
    }

    function _exception(
        bytes16[3] memory displacement,
        ExceptionParameters memory p
    ) private view returns (bytes16 energy, bytes16[3] memory forceOnA) {
        _finite(p.original);
        _finite(p.desired);
        _nonnegative(p.prefactor);
        _positive(p.alpha);
        FloatMath m = numericalMath;
        bytes16 r2 = _normSquared(displacement);
        if (m.isZero(r2)) {
            for (uint256 axis; axis < 3; ++axis)
                if (!m.isZero(displacement[axis])) revert OutsideDomain();
            if (!m.isZero(p.desired)) revert ZeroSeparation();
            energy = m.mul(TWO, m.mul(p.alpha, INV_SQRT_PI));
            energy = m.mul(energy, p.original);
            energy = m.neg(m.mul(energy, p.prefactor));
            _finite(energy);
            return (energy, forceOnA);
        }
        bytes16 r = m.sqrt(r2);
        bytes16 x = m.mul(p.alpha, r);
        if (m.compare(x, SIXTEEN) > 0) revert OutsideDomain();
        bytes16 erfX = scalarMath.erf(x);
        energy = m.mul(p.original, erfX);
        energy = m.div(m.sub(p.desired, energy), r);
        energy = m.mul(p.prefactor, energy);
        bytes16 scale = m.mul(
            p.original,
            _gaussianForceScale(x, r, r2, p.alpha, erfX)
        );
        bytes16 direct = m.mul(r2, r);
        direct = m.div(p.desired, direct);
        scale = m.sub(scale, direct);
        scale = m.mul(p.prefactor, scale);
        _finite(energy);
        for (uint256 axis; axis < 3; ++axis) {
            forceOnA[axis] = m.mul(scale, displacement[axis]);
            _finite(forceOnA[axis]);
        }
    }

    /// @dev Stable (erf(x)-2*x*exp(-x*x)/sqrt(pi))/r^3 at small x.
    function _gaussianForceScale(
        bytes16 x,
        bytes16 r,
        bytes16 r2,
        bytes16 alpha,
        bytes16 erfX
    ) private view returns (bytes16) {
        FloatMath m = numericalMath;
        if (m.compare(x, HALF) <= 0) {
            bytes16 negativeSquared = m.neg(m.mul(x, x));
            bytes16 term = ONE;
            bytes16 sum = m.div(ONE, m.fromUInt(3));
            for (uint256 n = 1; n < 24; ++n) {
                term = m.div(m.mul(term, negativeSquared), m.fromUInt(n));
                sum = m.add(sum, m.div(term, m.fromUInt(2 * n + 3)));
            }
            bytes16 factor = m.mul(alpha, alpha);
            factor = m.mul(factor, alpha);
            factor = m.mul(factor, m.mul(FOUR, INV_SQRT_PI));
            return m.mul(factor, sum);
        }
        bytes16 gaussian = scalarMath.exp(m.neg(m.mul(x, x)));
        bytes16 numerator = m.mul(INV_SQRT_PI, gaussian);
        numerator = m.mul(numerator, x);
        numerator = m.mul(TWO, numerator);
        numerator = m.sub(erfX, numerator);
        return m.div(numerator, m.mul(r2, r));
    }
}

contracts/core/PeriodicCellIndex.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";
import {ABDKMathQuad} from "../math/vendor/ABDKMathQuad.sol";

interface ICellSnapshotWords {
    function writer() external view returns (address);
    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32);
    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacity, bool isSealed);
    function snapshotInfo(bytes32 namespace) external view returns (
        bytes32 source, uint64 epoch, uint32 capacity, bytes32 writeDigest, bytes32 commitment
    );
}

/// @notice Bounded on-chain periodic cell membership from an authenticated snapshot.
/// @dev Candidate generation only. No force evaluator uses this index yet. Cell
///      members retain ascending global atom order; callers must merge neighboring
///      lists in canonical order and retain the original exact pair cutoff test.
contract PeriodicCellIndex {
    error Unauthorized();
    error InvalidInput();
    error UnsupportedDomain();
    error DependencyChanged();
    error WrongStage();
    error InvalidCursor();

    uint256 public constant MAX_BUILD_WORK = 32;
    uint256 public constant MAX_QUERY_ATOMS = 128;
    uint256 public constant MAX_AXIS_CELLS = 64;
    bytes32 public constant POLICY_ID = keccak256("ORVIA.PeriodicCellIndex.v1.GuardedBinary128.Fixed64");
    bytes16 private constant TWO = 0x40000000000000000000000000000000;
    bytes16 private constant MIN_BOX = 0x3fdf0000000000000000000000000000; // 2^-32
    bytes16 private constant MAX_BOX = 0x401f0000000000000000000000000000; // 2^32
    bytes16 private constant MIN_CUTOFF = 0x3fbf0000000000000000000000000000; // 2^-64
    bytes16 private constant MAX_COORDINATE_RATIO = 0x401d0000000000000000000000000000; // 2^30
    bytes16 private constant GRID_GUARD = 0x3fff0000000100000000000000000000; // 1+2^-32

    address public immutable owner;
    ExperimentRegistry public immutable registry;
    FloatMath public immutable numericalMath;
    OrthorhombicGeometry public immutable geometry;
    bytes32 public immutable registryCodeHash;
    bytes32 public immutable mathCodeHash;
    bytes32 public immutable geometryCodeHash;
    uint256 public nextIndex = 1;

    enum Stage { Missing, Building, Ready }
    struct Input {
        bytes32 protocol;
        address sourcePage;
        bytes32 sourceNamespace;
        uint32 atoms;
        uint32 positionOffset;
        uint32 positionStride;
        bytes16[3] box;
        bytes16 cutoff;
    }
    struct Index {
        Input input;
        Stage stage;
        uint32 builtAtoms;
        uint8[3] dimensions;
        uint32 totalCells;
        bytes32 snapshotCommitment;
        bytes32 sourceCodeHash;
        address sourceWriter;
        bytes32 sourceWriterCodeHash;
        bytes32 manifestHash;
        bytes32 commitment;
    }
    struct Cell { uint32 head; uint32 tail; }
    mapping(uint256 => Index) private _indices;
    mapping(uint256 => mapping(uint32 => Cell)) private _cells;
    mapping(uint256 => mapping(uint32 => uint32)) private _atomCells;
    mapping(uint256 => mapping(uint32 => uint32)) private _next;

    event IndexRegistered(uint256 indexed id, bytes32 indexed snapshotCommitment, bytes32 commitment);
    event IndexAdvanced(uint256 indexed id, uint32 builtAtoms, bool complete);

    constructor(address owner_, address registry_, address math_, address geometry_) {
        if (owner_ == address(0) || registry_.code.length == 0 || geometry_.code.length == 0
            || math_.codehash != keccak256(type(FloatMath).runtimeCode)) revert InvalidInput();
        if (address(OrthorhombicGeometry(geometry_).numericalMath()) != math_
            || OrthorhombicGeometry(geometry_).GEOMETRY_ID() != keccak256("ORVIA.OrthorhombicGeometry.v0.4")) revert InvalidInput();
        owner = owner_; registry = ExperimentRegistry(registry_); numericalMath = FloatMath(math_);
        geometry = OrthorhombicGeometry(geometry_);
        registryCodeHash = registry_.codehash; mathCodeHash = math_.codehash; geometryCodeHash = geometry_.codehash;
    }

    function registerIndex(Input calldata input) external returns (uint256 id) {
        if (msg.sender != owner) revert Unauthorized();
        if (input.atoms == 0 || input.positionStride < 3 || input.sourcePage.code.length == 0) revert InvalidInput();
        _dependencies(input.protocol);
        geometry.validateBox(input.box, input.cutoff);
        if (numericalMath.compare(input.cutoff, MIN_CUTOFF) < 0) revert UnsupportedDomain();
        (uint32 capacity, bool isSealed) = ICellSnapshotWords(input.sourcePage).namespaceInfo(input.sourceNamespace);
        (,,,,bytes32 snapshot) = ICellSnapshotWords(input.sourcePage).snapshotInfo(input.sourceNamespace);
        if (!isSealed || snapshot == bytes32(0) || uint256(input.positionOffset)
            + uint256(input.atoms - 1) * input.positionStride + 3 > capacity) revert InvalidInput();
        address sourceWriter = ICellSnapshotWords(input.sourcePage).writer();
        registry.assertModule(input.protocol, input.sourcePage, input.sourcePage.codehash);
        registry.assertModule(input.protocol, sourceWriter, sourceWriter.codehash);
        id = nextIndex++; Index storage index = _indices[id];
        index.input = input; index.stage = Stage.Building;
        index.snapshotCommitment = snapshot; index.sourceCodeHash = input.sourcePage.codehash;
        index.sourceWriter = sourceWriter; index.sourceWriterCodeHash = sourceWriter.codehash;
        index.manifestHash = registry.assertProtocol(input.protocol);
        bytes16 guardedCutoff = numericalMath.mul(input.cutoff, GRID_GUARD);
        uint32 total = 1;
        for (uint256 axis; axis < 3; ++axis) {
            if (numericalMath.compare(input.box[axis], MIN_BOX) < 0
                || numericalMath.compare(input.box[axis], MAX_BOX) > 0) revert UnsupportedDomain();
            bytes16 ratio = numericalMath.div(input.box[axis], guardedCutoff);
            uint256 cells = numericalMath.compare(ratio, numericalMath.fromUInt(MAX_AXIS_CELLS)) >= 0
                ? MAX_AXIS_CELLS : ABDKMathQuad.toUInt(ratio);
            if (cells == 0) revert UnsupportedDomain();
            index.dimensions[axis] = uint8(cells); total *= uint32(cells);
        }
        index.totalCells = total;
        index.commitment = keccak256(abi.encode(POLICY_ID, block.chainid, address(this), id, input,
            index.dimensions, index.manifestHash, snapshot, index.sourceCodeHash, sourceWriter,
            index.sourceWriterCodeHash, registryCodeHash, mathCodeHash, geometryCodeHash));
        emit IndexRegistered(id, snapshot, index.commitment);
    }

    function advanceBuild(uint256 id, uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_BUILD_WORK) revert InvalidInput();
        Index storage index = _get(id); _assertIndex(index);
        if (index.stage == Stage.Ready) return (0, true);
        while (processed < work && index.builtAtoms < index.input.atoms) {
            uint32 atom = index.builtAtoms;
            uint32 cell = _cellOf(index, _position(index, atom));
            Cell storage entry = _cells[id][cell]; uint32 pointer = atom + 1;
            if (entry.tail == 0) entry.head = pointer;
            else _next[id][entry.tail - 1] = pointer;
            entry.tail = pointer; _atomCells[id][atom] = cell;
            ++index.builtAtoms; ++processed;
        }
        complete = index.builtAtoms == index.input.atoms;
        if (complete) index.stage = Stage.Ready;
        emit IndexAdvanced(id, index.builtAtoms, complete);
    }

    /// @notice Derive and deduplicate the <=27 neighboring cells on chain.
    /// @dev Heads are atom+1 pointers; zero means an empty list. This does not
    ///      filter self/coincident atoms, exclusions or distance-to-cutoff.
    function neighboringCells(uint256 id, uint32 atom) external view returns (
        uint32[27] memory cellIds, uint32[27] memory heads, uint8 count
    ) {
        Index storage index = _ready(id); if (atom >= index.input.atoms) revert InvalidInput();
        uint32 cell = _atomCells[id][atom];
        for (uint256 choice; choice < 27; ++choice) {
            uint32 neighbor = _neighbor(cell, index.dimensions, choice);
            bool seen;
            for (uint256 i; i < count; ++i) if (cellIds[i] == neighbor) { seen = true; break; }
            if (!seen) { cellIds[count] = neighbor; heads[count] = _cells[id][neighbor].head; ++count; }
        }
    }

    function _neighbor(uint32 cell, uint8[3] memory dimensions, uint256 choice) private pure returns (uint32) {
        uint256 nx = dimensions[0]; uint256 ny = dimensions[1]; uint256 nz = dimensions[2];
        uint256 x = cell % nx; uint256 y = (cell / nx) % ny; uint256 z = cell / (nx * ny);
        return uint32((x + nx + choice % 3 - 1) % nx
            + nx * (((y + ny + (choice / 3) % 3 - 1) % ny) + ny * ((z + nz + choice / 9 - 1) % nz)));
    }

    /// @notice Read <=128 ascending atom IDs from one cell, with bounded work.
    /// @dev cursor=0 starts at the head. Returned next=0 means complete; stop then.
    ///      A nonzero cursor must be a real atom+1 member of this exact cell/index.
    function cellAtoms(uint256 id, uint32 cell, uint32 cursor, uint256 count) external view returns (
        uint32[] memory atoms, uint32 next, bool complete
    ) {
        Index storage index = _ready(id);
        if (cell >= index.totalCells || count == 0 || count > MAX_QUERY_ATOMS) revert InvalidInput();
        uint32 pointer = cursor == 0 ? _cells[id][cell].head : cursor;
        if (pointer > index.input.atoms || (pointer != 0 && _atomCells[id][pointer - 1] != cell)) revert InvalidCursor();
        atoms = new uint32[](count); uint256 used;
        while (pointer != 0 && used < count) {
            atoms[used++] = pointer - 1; pointer = _next[id][pointer - 1];
        }
        assembly { mstore(atoms, used) }
        return (atoms, pointer, pointer == 0);
    }

    function atomCell(uint256 id, uint32 atom) external view returns (uint32) {
        Index storage index = _ready(id); if (atom >= index.input.atoms) revert InvalidInput();
        return _atomCells[id][atom];
    }
    /// @notice The next atom+1 pointer in this atom's sorted cell list, or zero.
    function nextAtom(uint256 id, uint32 atom) external view returns (uint32) {
        Index storage index = _ready(id); if (atom >= index.input.atoms) revert InvalidInput();
        return _next[id][atom];
    }
    function indexInfo(uint256 id) external view returns (
        Stage stage, uint32 builtAtoms, uint8[3] memory dimensions, uint32 totalCells,
        bytes32 snapshotCommitment, bytes32 commitment, Input memory input
    ) {
        Index storage index = _get(id);
        return (index.stage, index.builtAtoms, index.dimensions, index.totalCells,
            index.snapshotCommitment, index.commitment, index.input);
    }

    function _cellOf(Index storage index, bytes16[3] memory position) private view returns (uint32) {
        FloatMath m = numericalMath;
        for (uint256 axis; axis < 3; ++axis) {
            if (m.compare(m.div(m.abs(position[axis]), index.input.box[axis]), MAX_COORDINATE_RATIO) > 0) revert UnsupportedDomain();
        }
        bytes16[3] memory zero;
        bytes16[3] memory periodic = geometry.displacement(zero, position, index.input.box);
        uint32 cell; uint32 multiplier = 1;
        for (uint256 axis; axis < 3; ++axis) {
            cell += _bin(periodic[axis], index.input.box[axis], index.dimensions[axis]) * multiplier;
            multiplier *= index.dimensions[axis];
        }
        return cell;
    }
    function _bin(bytes16 periodic, bytes16 length, uint8 cells) private view returns (uint32) {
        FloatMath m = numericalMath;
        bytes16 wrapped = m.add(periodic, m.div(length, TWO));
        if (m.compare(wrapped, bytes16(0)) < 0) revert UnsupportedDomain();
        if (m.compare(wrapped, length) >= 0) wrapped = bytes16(0);
        bytes16 scaled = m.mul(wrapped, m.fromUInt(cells));
        uint256 coordinate = ABDKMathQuad.toUInt(m.div(scaled, length));
        // A final rounding at the periodic upper boundary is the same cell
        // as zero; the documented conservative margin covers this binning.
        if (coordinate == cells) coordinate = 0;
        if (coordinate >= cells) revert UnsupportedDomain();
        return uint32(coordinate);
    }
    function _position(Index storage index, uint32 atom) private view returns (bytes16[3] memory position) {
        uint256 start = uint256(index.input.positionOffset) + uint256(atom) * index.input.positionStride;
        for (uint256 axis; axis < 3; ++axis) {
            bytes32 word = ICellSnapshotWords(index.input.sourcePage).readWord(index.input.sourceNamespace, start + axis);
            if (uint256(word) >> 128 != 0) revert InvalidInput();
            bytes16 value = bytes16(uint128(uint256(word)));
            if (!numericalMath.isFinite(value)) revert InvalidInput();
            position[axis] = value;
        }
    }
    function _dependencies(bytes32 protocol) private view {
        if (address(registry).codehash != registryCodeHash || address(numericalMath).codehash != mathCodeHash
            || address(geometry).codehash != geometryCodeHash) revert DependencyChanged();
        registry.assertModule(protocol, address(this), address(this).codehash);
        registry.assertModule(protocol, address(numericalMath), mathCodeHash);
        registry.assertModule(protocol, address(geometry), geometryCodeHash);
    }
    function _assertIndex(Index storage index) private view {
        _dependencies(index.input.protocol);
        if (registry.assertProtocol(index.input.protocol) != index.manifestHash
            || index.input.sourcePage.codehash != index.sourceCodeHash
            || index.sourceWriter.codehash != index.sourceWriterCodeHash) revert DependencyChanged();
        registry.assertModule(index.input.protocol, index.input.sourcePage, index.sourceCodeHash);
        registry.assertModule(index.input.protocol, index.sourceWriter, index.sourceWriterCodeHash);
        (,,,,bytes32 snapshot) = ICellSnapshotWords(index.input.sourcePage).snapshotInfo(index.input.sourceNamespace);
        if (snapshot != index.snapshotCommitment) revert DependencyChanged();
    }
    function _get(uint256 id) private view returns (Index storage index) {
        index = _indices[id]; if (index.stage == Stage.Missing) revert InvalidInput();
    }
    function _ready(uint256 id) private view returns (Index storage index) {
        index = _get(id); _assertIndex(index); if (index.stage != Stage.Ready) revert WrongStage();
    }
}

contracts/core/OrderedNeighborPairs.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PeriodicCellIndex} from "./PeriodicCellIndex.sol";

/// @notice Canonical i<j traversal of an authenticated periodic cell index.
/// @dev Only the immutable consumer can pull pairs. Its force operation and this
///      cursor update must share a transaction, so a failure rolls both back.
///      This module is not connected to AlchemicalHamiltonianEvaluator yet.
contract OrderedNeighborPairs {
    error Unauthorized();
    error InvalidInput();
    error DependencyChanged();

    uint256 public constant MAX_WORK = 32;
    bytes32 public constant POLICY_ID = keccak256("ORVIA.OrderedNeighborPairs.v1.Packed27Heads");
    address public immutable owner;
    bytes32 public immutable ownerCodeHash;
    PeriodicCellIndex public immutable cellIndex;
    bytes32 public immutable cellIndexCodeHash;
    uint256 public nextTraversal = 1;

    struct Traversal {
        uint256 index;
        bytes32 indexCommitment;
        bytes32 commitment;
        uint32 atoms;
        uint32 row;
        uint8 headCount;
        bool initialized;
        bool complete;
        uint64 visited;
        uint64 emitted;
        uint256[4] heads;
    }
    mapping(uint256 => Traversal) private _traversals;
    event TraversalRegistered(uint256 indexed traversal, uint256 indexed index, bytes32 commitment);
    event TraversalAdvanced(uint256 indexed traversal, uint256 processed, uint32 row, bool complete);

    constructor(address owner_, address cellIndex_) {
        if (owner_.code.length == 0 || cellIndex_.code.length == 0) revert InvalidInput();
        if (PeriodicCellIndex(cellIndex_).POLICY_ID()
            != keccak256("ORVIA.PeriodicCellIndex.v1.GuardedBinary128.Fixed64")) revert InvalidInput();
        owner = owner_; ownerCodeHash = owner_.codehash;
        cellIndex = PeriodicCellIndex(cellIndex_); cellIndexCodeHash = cellIndex_.codehash;
    }

    modifier onlyOwner() {
        if (msg.sender != owner || owner.codehash != ownerCodeHash) revert Unauthorized();
        _;
    }

    function registerTraversal(uint256 index) external onlyOwner returns (uint256 id) {
        _dependencies();
        (PeriodicCellIndex.Stage stage,,,,,bytes32 indexCommitment,PeriodicCellIndex.Input memory input) = cellIndex.indexInfo(index);
        if (stage != PeriodicCellIndex.Stage.Ready) revert InvalidInput();
        cellIndex.atomCell(index, 0); // Recheck source, snapshot and complete protocol identity.
        id = nextTraversal++; Traversal storage traversal = _traversals[id];
        traversal.index = index; traversal.atoms = input.atoms; traversal.indexCommitment = indexCommitment;
        traversal.commitment = keccak256(abi.encode(POLICY_ID,block.chainid,address(this),id,
            owner,ownerCodeHash,address(cellIndex),cellIndexCodeHash,index,indexCommitment,input.atoms));
        emit TraversalRegistered(id,index,traversal.commitment);
    }

    /// @notice Consume bounded setup/pop/skip work and return at most one pair.
    /// @dev No externally supplied cursor or pair can change coverage. Zero useful
    ///      pairs is a valid page, but every nonterminal call consumes work.
    function advance(uint256 id, uint256 work) external onlyOwner returns (
        uint256 processed, bool found, uint32 a, uint32 b, bool complete
    ) {
        if (work == 0 || work > MAX_WORK) revert InvalidInput();
        _dependencies(); Traversal storage traversal = _get(id);
        cellIndex.atomCell(traversal.index, 0); // Required even after terminal completion.
        if (traversal.complete) return (0,false,0,0,true);
        while (processed < work && !traversal.complete) {
            ++processed;
            if (!traversal.initialized) { _beginRow(traversal); continue; }
            (uint32 pointer,uint256 position) = _minimum(traversal);
            if (pointer == 0) {
                ++traversal.row; traversal.initialized = false;
                if (traversal.row == traversal.atoms) traversal.complete = true;
                continue;
            }
            uint32 atom = pointer - 1;
            _setHead(traversal,position,cellIndex.nextAtom(traversal.index,atom));
            ++traversal.visited;
            if (atom > traversal.row) {
                ++traversal.emitted;
                emit TraversalAdvanced(id,processed,traversal.row,false);
                return (processed,true,traversal.row,atom,false);
            }
        }
        complete = traversal.complete;
        emit TraversalAdvanced(id,processed,traversal.row,complete);
    }

    function traversalInfo(uint256 id) external view returns (
        uint256 index, bytes32 indexCommitment, bytes32 commitment, uint32 atoms, uint32 row,
        bool complete, uint64 visited, uint64 emitted
    ) {
        Traversal storage traversal = _get(id);
        return (traversal.index,traversal.indexCommitment,traversal.commitment,traversal.atoms,
            traversal.row,traversal.complete,traversal.visited,traversal.emitted);
    }

    function _beginRow(Traversal storage traversal) private {
        (,uint32[27] memory heads,uint8 count) = cellIndex.neighboringCells(traversal.index,traversal.row);
        uint256[4] memory packed;
        for (uint256 i; i < count; ++i) packed[i / 8] |= uint256(heads[i]) << ((i % 8) * 32);
        traversal.heads = packed; traversal.headCount = count; traversal.initialized = true;
    }
    function _minimum(Traversal storage traversal) private view returns (uint32 pointer,uint256 position) {
        for (uint256 i; i < traversal.headCount; ++i) {
            uint32 head = uint32(traversal.heads[i / 8] >> ((i % 8) * 32));
            if (head != 0 && (pointer == 0 || head < pointer)) { pointer = head; position = i; }
        }
    }
    function _setHead(Traversal storage traversal,uint256 position,uint32 next) private {
        uint256 shift = (position % 8) * 32;
        uint256 mask = uint256(type(uint32).max) << shift;
        uint256 slot = position / 8;
        traversal.heads[slot] = (traversal.heads[slot] & ~mask) | (uint256(next) << shift);
    }
    function _dependencies() private view {
        if (address(cellIndex).codehash != cellIndexCodeHash) revert DependencyChanged();
    }
    function _get(uint256 id) private view returns (Traversal storage traversal) {
        traversal = _traversals[id]; if (traversal.commitment == bytes32(0)) revert InvalidInput();
    }
}

contracts/core/AlchemicalHamiltonianEval.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {AlchemicalTopologyCatalog} from "./AlchemicalTopologyCatalog.sol";
import {ExperimentRegistry} from "./ExperimentRegistry.sol";
import {FloatMath} from "../math/FloatMath.sol";
import {HarmonicBondKernel} from "../kernels/HarmonicBondKernel.sol";
import {HarmonicAngleKernel} from "../kernels/HarmonicAngleKernel.sol";
import {PeriodicTorsionKernel} from "../kernels/PeriodicTorsionKernel.sol";
import {LennardJonesKernel} from "../kernels/LennardJonesKernel.sol";
import {SoftcoreLennardJonesKernel} from "../kernels/SoftcoreLennardJonesKernel.sol";
import {OrthorhombicGeometry} from "../kernels/OrthorhombicGeometry.sol";
import {EwaldRealSpaceKernel} from "../kernels/EwaldRealSpaceKernel.sol";
import {EwaldReciprocalKernel} from "../kernels/EwaldReciprocalKernel.sol";
import {EwaldCorrections} from "../kernels/EwaldCorrections.sol";

interface IProductionWordState {
    function writer() external view returns (address);
    function createNamespace(bytes32 id, uint32 capacity) external;
    function writeWord(bytes32 id, uint256 index, bytes32 value) external;
    function writeWords(bytes32 id, uint256 start, bytes32[] calldata values) external;
    function readWord(bytes32 id, uint256 index) external view returns (bytes32);
    function namespaceInfo(bytes32 id) external view returns (uint32 capacity, bool isSealed);
    function sealNamespace(bytes32 id) external;
    function snapshotNamespace(bytes32 source, bytes32 snapshot) external returns (bytes32);
    function snapshotInfo(bytes32 id) external view returns (bytes32 source, uint64 epoch, uint32 capacity, bytes32 writeDigest, bytes32 commitment);
}
interface IProductionMathIdentity { function numericalMath() external view returns (address); }

/// @notice One complete on-chain hybrid Hamiltonian on an immutable molecular snapshot.
/// @dev NVT fixed orthorhombic box; bonded endpoint interpolation, switched dual
///      soft-core LJ and interpolated-charge finite tin-foil Ewald. No CMAP,
///      Urey-Bradley, harmonic improper, constraints, PME or tail correction is
///      silently supplied. The catalog accepts only its explicit supported schema.
contract AlchemicalHamiltonianEvaluator {
    error Unauthorized(); error InvalidInput(); error WrongStage(); error DependencyChanged(); error NotConfigured();
    enum Stage { Missing, Atoms, Bonds, Angles, Torsions, Exceptions, Pairs, ModeSetup, StructureFactor, ModeForces, Background, Complete }
    struct Modules {
        address registry; address topology; address math; address geometry;
        address bond; address angle; address torsion; address lj; address softcore;
        address realSpace; address reciprocal; address corrections;
    }
    struct Input { bytes32 protocol; bytes32 topology; uint8 state; address sourcePage; bytes32 sourceNamespace; uint32 offset; uint32 stride; }
    struct Run {
        Input input; Stage stage; uint64 cursor; uint64 pairs; uint32 modeIndex; uint32 modes;
        bytes32 topologyCommitment; bytes32 snapshotCommitment; bytes32 sourceHash; bytes32 sourceWriterHash;
        address sourceWriter; bytes32 outputNamespace; bytes32 commitment;
        bytes16 lambda; bytes16 totalCharge; bool anyCharge; bool fastCutoffEligible;
        int32[3] mode; bytes16[3] wave; bytes16 coefficient; bytes16 cosine; bytes16 sine;
    }
    struct Pair { uint32 a; uint32 b; uint32 kind; bytes16 sigmaA; bytes16 epsilonA; bytes16 desiredA; bytes16 sigmaB; bytes16 epsilonB; bytes16 desiredB; }
    struct Evaluation { bytes16 energy; bytes16[3][4] forces; }
    address public immutable owner;
    Modules public modules;
    bytes32[12] public moduleHashes;
    bytes32 public immutable coreConfigurationHash;
    IProductionWordState public outputPage;
    bytes32 public outputPageHash;
    uint256 public nextEvaluation = 1;
    uint256 public constant MAX_WORK = 8;
    bytes16 private constant ONE = 0x3fff0000000000000000000000000000;
    bytes16 private constant TWO = 0x40000000000000000000000000000000;
    mapping(uint256 => Run) private runs;
    mapping(uint256 => mapping(uint64 => uint64)) private exceptionIndex;
    event EvaluationRegistered(uint256 indexed id, bytes32 commitment, bytes32 snapshotCommitment);
    event EvaluationAdvanced(uint256 indexed id, Stage stage, uint64 cursor, uint32 mode);

    constructor(address owner_, Modules memory m) {
        if (owner_ == address(0)) revert InvalidInput(); owner = owner_; modules = m;
        address[12] memory addresses = _addresses(m);
        for (uint256 i; i < 12; ++i) {
            if (addresses[i].code.length == 0) revert InvalidInput(); moduleHashes[i] = addresses[i].codehash;
            if (i >= 3 && IProductionMathIdentity(addresses[i]).numericalMath() != m.math) revert InvalidInput();
        }
        if (address(AlchemicalTopologyCatalog(m.topology).numericalMath()) != m.math
            || address(AlchemicalTopologyCatalog(m.topology).geometry()) != m.geometry) revert InvalidInput();
        // All Ewald kernels must share their actual scalar implementation.
        if (address(EwaldRealSpaceKernel(m.realSpace).scalarMath()) != address(EwaldCorrections(m.corrections).scalarMath())
            || address(EwaldRealSpaceKernel(m.realSpace).scalarMath()) != address(EwaldReciprocalKernel(m.reciprocal).scalarMath())) revert InvalidInput();
        coreConfigurationHash = keccak256(abi.encode(m, moduleHashes));
    }
    function bindOutputPage(address page) external {
        if (msg.sender != owner) revert Unauthorized(); if (address(outputPage) != address(0)) revert WrongStage();
        if (page.code.length == 0 || IProductionWordState(page).writer() != address(this)) revert InvalidInput();
        outputPage = IProductionWordState(page); outputPageHash = page.codehash;
    }
    function registerEvaluation(bytes32 protocolId, bytes32 topologyId, uint8 state, address sourcePage,
        bytes32 sourceNamespace, uint32 offset, uint32 stride) external returns (uint256 id)
    {
        if (msg.sender != owner) revert Unauthorized();
        return _register(Input(protocolId,topologyId,state,sourcePage,sourceNamespace,offset,stride));
    }
    function _register(Input memory input) private returns(uint256 id) {
        bytes32 manifest = _dependencies(input.protocol);
        AlchemicalTopologyCatalog catalog = AlchemicalTopologyCatalog(modules.topology);
        bytes32 topologyCommitment = catalog.assertTopology(input.topology);
        AlchemicalTopologyCatalog.Definition memory d = catalog.definition(input.topology);
        if (input.state >= catalog.stateCount(input.topology) || input.sourcePage.code.length == 0 || input.stride < 3) revert InvalidInput();
        bytes32 snapshot = _checkSource(input,d.atoms);
        id = nextEvaluation++; Run storage r = runs[id];
        r.input = input;
        r.stage = Stage.Atoms; r.pairs = uint64(uint256(d.atoms) * (d.atoms - 1) / 2);
        r.topologyCommitment = topologyCommitment; r.snapshotCommitment = snapshot;
        r.sourceHash = input.sourcePage.codehash;
        r.sourceWriter = IProductionWordState(input.sourcePage).writer(); r.sourceWriterHash = r.sourceWriter.codehash;
        r.lambda = catalog.lambdaAt(input.topology, input.state); r.modes = _modeCount(d.ewaldExtent);
        r.fastCutoffEligible = _cutoffBounded(d.box[0]) && _cutoffBounded(d.box[1]) && _cutoffBounded(d.box[2]);
        r.outputNamespace = keccak256(abi.encode(bytes32("ORVIA-HAMILTONIAN-OUTPUT-v1"), block.chainid, address(this), id));
        r.commitment = _commitment(r,id,manifest);
        outputPage.createNamespace(r.outputNamespace, d.atoms * 3 + 10);
        emit EvaluationRegistered(id, r.commitment, snapshot);
    }
    function _checkSource(Input memory input,uint32 atoms) private view returns(bytes32 snapshot) {
        (uint32 capacity, bool frozen) = IProductionWordState(input.sourcePage).namespaceInfo(input.sourceNamespace);
        (,,,,snapshot) = IProductionWordState(input.sourcePage).snapshotInfo(input.sourceNamespace);
        if (!frozen || snapshot == bytes32(0) || uint256(input.offset) + uint256(atoms - 1) * input.stride + 3 > capacity) revert InvalidInput();
        address writer = IProductionWordState(input.sourcePage).writer();
        ExperimentRegistry(modules.registry).assertModule(input.protocol, input.sourcePage, input.sourcePage.codehash);
        ExperimentRegistry(modules.registry).assertModule(input.protocol, writer, writer.codehash);
    }
    function _commitment(Run storage r,uint256 id,bytes32 manifest) private view returns(bytes32) {
        bytes32 source = keccak256(abi.encode(r.input,r.snapshotCommitment,r.sourceHash,r.sourceWriter,r.sourceWriterHash));
        bytes32 configuration = keccak256(abi.encode(coreConfigurationHash,address(outputPage),outputPageHash));
        return keccak256(abi.encode(bytes32("ORVIA-HAMILTONIAN-v1"), block.chainid, address(this), id,
            manifest, configuration, r.topologyCommitment, source));
    }
    function advance(uint256 id, uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_WORK) revert InvalidInput(); Run storage r = _get(id);
        _assertRun(r);
        // Anyone may finish this job before its pipeline writer next advances.
        // Preserve authenticated completed results for that writer to consume.
        if (r.stage == Stage.Complete) return (0, true);
        AlchemicalTopologyCatalog.Definition memory d = AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology);
        while (processed < work && r.stage != Stage.Complete) { _one(id, r, d); ++processed; }
        complete = r.stage == Stage.Complete; emit EvaluationAdvanced(id, r.stage, r.cursor, r.modeIndex);
    }
    function result(uint256 id) external view returns (bytes32 outputNamespace, bytes32 commitment, bytes16 energy) {
        Run storage r = _get(id); if (r.stage != Stage.Complete) revert WrongStage(); _assertRun(r);
        AlchemicalTopologyCatalog.Definition memory d = AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology);
        return (r.outputNamespace, r.commitment, _decode(outputPage.readWord(r.outputNamespace, uint256(d.atoms) * 3)));
    }
    function forceAt(uint256 id, uint32 atom) external view returns (bytes16[3] memory force) {
        Run storage r = _get(id); if (r.stage != Stage.Complete) revert WrongStage(); _assertRun(r);
        if (atom >= AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology).atoms) revert InvalidInput();
        for (uint256 axis; axis < 3; ++axis) force[axis] = _decode(outputPage.readWord(r.outputNamespace, uint256(atom) * 3 + axis));
    }
    function components(uint256 id) external view returns (bytes16[10] memory values) {
        Run storage r = _get(id); if (r.stage != Stage.Complete) revert WrongStage(); _assertRun(r);
        uint256 start = uint256(AlchemicalTopologyCatalog(modules.topology).definition(r.input.topology).atoms) * 3;
        for (uint256 k; k < 10; ++k) values[k] = _decode(outputPage.readWord(r.outputNamespace, start + k));
    }
    function moduleConfiguration()external view returns(Modules memory){return modules;}
    function runInfo(uint256 id) external view returns (Stage stage, uint64 cursor, uint32 mode, Input memory input, bytes32 snapshotCommitment) {
        Run storage r = _get(id); return (r.stage, r.cursor, r.modeIndex, r.input, r.snapshotCommitment);
    }
    function _one(uint256 id, Run storage r, AlchemicalTopologyCatalog.Definition memory d) private {
        FloatMath m = FloatMath(modules.math);
        if (r.stage == Stage.Atoms) {
            bytes16[3] memory position = _position(r, uint32(r.cursor)); bytes16 q = _charge(r, d, uint32(r.cursor));
            r.anyCharge = r.anyCharge || !m.isZero(q); r.totalCharge = m.add(r.totalCharge, q);
            _energy(r, d, 6, EwaldCorrections(modules.corrections).selfEnergy(q, d.ewaldAlpha, d.prefactor));
            if (r.fastCutoffEligible && !_cutoffAtomSafe(d, uint32(r.cursor), position, q)) r.fastCutoffEligible = false;
            if (++r.cursor == d.atoms) { r.cursor = 0; r.stage = Stage.Bonds; }
        } else if (r.stage == Stage.Bonds || r.stage == Stage.Angles || r.stage == Stage.Torsions) {
            uint64 count = r.stage == Stage.Bonds ? d.bonds : r.stage == Stage.Angles ? d.angles : d.torsions;
            if (count != 0) { _bonded(r, d); ++r.cursor; }
            if (r.cursor == count) { r.cursor = 0; r.stage = Stage(uint8(r.stage) + 1); }
        } else if (r.stage == Stage.Exceptions) {
            if (d.exceptions != 0) {
                Pair memory p = _exception(r, d, r.cursor);
                exceptionIndex[id][uint64(uint256(p.a) * d.atoms + p.b)] = r.cursor + 1;
                _exceptionPair(r, d, p); ++r.cursor;
            }
            if (r.cursor == d.exceptions) { r.cursor = 0; r.stage = Stage.Pairs; }
        } else if (r.stage == Stage.Pairs) {
            (uint32 a, uint32 b) = _pairIndices(r.cursor, d.atoms);
            if (exceptionIndex[id][uint64(uint256(a) * d.atoms + b)] == 0) _normalPair(r, d, a, b);
            if (++r.cursor == r.pairs) { r.cursor = 0; r.stage = r.anyCharge ? Stage.ModeSetup : Stage.Background; }
        } else if (r.stage == Stage.ModeSetup) {
            r.mode = _modeAt(r.modeIndex, d.ewaldExtent);
            (r.wave, r.coefficient) = EwaldReciprocalKernel(modules.reciprocal).waveVector(r.mode, d.box, d.ewaldAlpha, d.prefactor);
            r.cosine = bytes16(0); r.sine = bytes16(0); r.cursor = 0; r.stage = Stage.StructureFactor;
        } else if (r.stage == Stage.StructureFactor) {
            (bytes16 c, bytes16 s) = _term(r, d, uint32(r.cursor)); r.cosine = m.add(r.cosine, c); r.sine = m.add(r.sine, s);
            if (++r.cursor == d.atoms) {
                _energy(r, d, 5, EwaldReciprocalKernel(modules.reciprocal).modeEnergy(r.coefficient, r.cosine, r.sine));
                r.cursor = 0; r.stage = Stage.ModeForces;
            }
        } else if (r.stage == Stage.ModeForces) {
            (bytes16 c, bytes16 s) = _term(r, d, uint32(r.cursor));
            _force(r, uint32(r.cursor), EwaldReciprocalKernel(modules.reciprocal).forceContribution(r.wave, r.coefficient, c, s, r.cosine, r.sine), false);
            if (++r.cursor == d.atoms) { r.cursor = 0; r.stage = ++r.modeIndex == r.modes ? Stage.Background : Stage.ModeSetup; }
        } else if (r.stage == Stage.Background) {
            _energy(r, d, 7, EwaldCorrections(modules.corrections).backgroundEnergy(r.totalCharge, d.box, d.ewaldAlpha, d.prefactor));
            outputPage.sealNamespace(r.outputNamespace); r.stage = Stage.Complete;
        } else revert WrongStage();
    }
    function _bonded(Run storage r, AlchemicalTopologyCatalog.Definition memory d) private {
        uint32[4] memory atoms; uint64 width = r.stage == Stage.Bonds ? 4 : r.stage == Stage.Angles ? 5 : 7;
        uint64 n = r.stage == Stage.Bonds ? 2 : r.stage == Stage.Angles ? 3 : 4;
        bytes32 sa = r.stage == Stage.Bonds ? d.a.bonds : r.stage == Stage.Angles ? d.a.angles : d.a.torsions;
        bytes32 sb = r.stage == Stage.Bonds ? d.b.bonds : r.stage == Stage.Angles ? d.b.angles : d.b.torsions;
        for (uint64 k; k < n; ++k) atoms[k] = uint32(uint256(_word(sa, r.cursor * width + k)));
        Evaluation memory a;
        Evaluation memory b;
        if(r.lambda==ONE){b=_bondedEndpoint(r,d,sb,width,atoms);a=b;}
        else{a=_bondedEndpoint(r,d,sa,width,atoms);b=r.lambda==bytes16(0)||sa==sb?a:_bondedEndpoint(r,d,sb,width,atoms);}
        _energy(r, d, uint8(r.stage) - uint8(Stage.Bonds), _mix(a.energy, b.energy, r.lambda));
        for (uint256 k; k < n; ++k) _force(r, atoms[k], _mixVector(a.forces[k], b.forces[k], r.lambda), false);
    }
    function _bondedEndpoint(Run storage r, AlchemicalTopologyCatalog.Definition memory d, bytes32 stream, uint64 width, uint32[4] memory atoms)
        private view returns (Evaluation memory e)
    {
        if(width==4)return _bondEvaluation(r,d,stream,atoms);
        if(width==5)return _angleEvaluation(r,d,stream,atoms);
        return _torsionEvaluation(r,d,stream,atoms);
    }
    function _bondEvaluation(Run storage r,AlchemicalTopologyCatalog.Definition memory d,bytes32 stream,uint32[4] memory atoms)private view returns(Evaluation memory e){
        bytes16 k=_value(stream,r.cursor*4+2);if(k==bytes16(0))return e;
        bytes16 r0=_value(stream,r.cursor*4+3);
        bytes16[3] memory zero;
        bytes16[3] memory displacement=_bondedDisplacement(r,d,atoms[0],atoms[1]);
        (e.energy,e.forces[0])=HarmonicBondKernel(modules.bond).evaluate(zero,displacement,k,r0);
        e.forces[1]=_negative(e.forces[0]);
    }
    function _angleEvaluation(Run storage r,AlchemicalTopologyCatalog.Definition memory d,bytes32 stream,uint32[4] memory atoms)private view returns(Evaluation memory e){
        bytes16 k=_value(stream,r.cursor*5+3);if(k==bytes16(0))return e;bytes16 theta=_value(stream,r.cursor*5+4);
        bytes16[3] memory zero;bytes16[3] memory a=_bondedDisplacement(r,d,atoms[1],atoms[0]);bytes16[3] memory c=_bondedDisplacement(r,d,atoms[1],atoms[2]);
        (e.energy,e.forces[0],e.forces[1],e.forces[2])=HarmonicAngleKernel(modules.angle).evaluate(a,zero,c,k,theta);
    }
    function _torsionEvaluation(Run storage r,AlchemicalTopologyCatalog.Definition memory d,bytes32 stream,uint32[4] memory atoms)private view returns(Evaluation memory e){
        bytes16 k=_value(stream,r.cursor*7+5);if(k==bytes16(0))return e;
        bytes16[3][4] memory p;p[0]=_bondedDisplacement(r,d,atoms[1],atoms[0]);p[2]=_bondedDisplacement(r,d,atoms[1],atoms[2]);
        bytes16[3] memory last=_bondedDisplacement(r,d,atoms[2],atoms[3]);
        for(uint256 axis;axis<3;++axis)p[3][axis]=FloatMath(modules.math).add(p[2][axis],last[axis]);
        uint32 n=uint32(uint256(_word(stream,r.cursor*7+4)));bytes16 phase=_value(stream,r.cursor*7+6);
        return _torsionCall(p,n,k,phase);
    }
    function _torsionCall(bytes16[3][4] memory p,uint32 n,bytes16 k,bytes16 phase)private view returns(Evaluation memory e){
        (e.energy,e.forces[0],e.forces[1],e.forces[2],e.forces[3])=PeriodicTorsionKernel(modules.torsion).evaluate(p[0],p[1],p[2],p[3],n,k,phase);
    }
    function _normalPair(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 a, uint32 b) private {
        bytes16[3] memory displacement = _displacement(r, d, a, b);
        if (r.fastCutoffEligible) {
            FloatMath m = FloatMath(modules.math);
            bytes16 squared;
            for (uint256 k; k < 3; ++k) squared = m.add(squared, m.mul(displacement[k], displacement[k]));
            // Same ordered binary128 r^2 and sqrt as the legacy LJ/Ewald
            // branches. Never substitute a rounded cutoff-squared comparison.
            if (m.compare(m.sqrt(squared), d.cutoff) >= 0) return;
        }
        Pair memory p; p.a = a; p.b = b;
        (p.sigmaA, p.epsilonA) = _mixParticle(d.a.nonbonded, a, b);
        (p.sigmaB, p.epsilonB) = _mixParticle(d.b.nonbonded, a, b);
        (bytes16 energy, bytes16[3] memory force) = _lj(r, d, p, displacement, false);
        _energy(r, d, 3, energy); _force(r, a, force, false); _force(r, b, force, true);
        bytes16 chargeProduct = FloatMath(modules.math).mul(_charge(r, d, a), _charge(r, d, b));
        if (chargeProduct != bytes16(0)) {
            (energy, force) = EwaldRealSpaceKernel(modules.realSpace).evaluate(displacement,
                chargeProduct, d.prefactor, d.ewaldAlpha, d.cutoff);
            _energy(r, d, 4, energy); _force(r, a, force, false); _force(r, b, force, true);
        }
    }
    // Eligibility only removes arithmetic known to be finite outside the
    // cutoff. Extreme admitted inputs retain every legacy failure path.
    function _cutoffBounded(bytes16 value) private pure returns (bool) {
        return (uint128(value) & 0x7fffffffffffffffffffffffffffffff) <= 0x40ff0000000000000000000000000000; // abs <= 2^256
    }
    function _cutoffAtomSafe(AlchemicalTopologyCatalog.Definition memory d, uint32 atom, bytes16[3] memory position, bytes16 charge) private view returns (bool) {
        if (!_cutoffBounded(position[0]) || !_cutoffBounded(position[1]) || !_cutoffBounded(position[2]) || !_cutoffBounded(charge)) return false;
        uint64 offset = uint64(atom) * 3;
        return _cutoffBounded(_value(d.a.nonbonded, offset)) && _cutoffBounded(_value(d.a.nonbonded, offset + 1))
            && _cutoffBounded(_value(d.b.nonbonded, offset)) && _cutoffBounded(_value(d.b.nonbonded, offset + 1));
    }
    function _exceptionPair(Run storage r, AlchemicalTopologyCatalog.Definition memory d, Pair memory p) private {
        bytes16[3] memory displacement = _bondedDisplacement(r, d, p.a, p.b);
        if (p.kind == 2) {
            (bytes16 e, bytes16[3] memory f) = _lj(r, d, p, displacement, true);
            _energy(r, d, 3, e); _force(r, p.a, f, false); _force(r, p.b, f, true);
        }
        if (r.anyCharge || p.desiredA != bytes16(0) || p.desiredB != bytes16(0)) {
            (bytes16 e, bytes16[3] memory f) = EwaldCorrections(modules.corrections).exception(displacement,
                FloatMath(modules.math).mul(_charge(r, d, p.a), _charge(r, d, p.b)), _mix(p.desiredA, p.desiredB, r.lambda), d.prefactor, d.ewaldAlpha);
            _energy(r, d, 8, e); _force(r, p.a, f, false); _force(r, p.b, f, true);
        }
    }
    function _lj(Run storage r, AlchemicalTopologyCatalog.Definition memory d, Pair memory p, bytes16[3] memory displacement, bool direct)
        private view returns (bytes16 energy, bytes16[3] memory force)
    {
        FloatMath m = FloatMath(modules.math);
        if (p.epsilonA == bytes16(0) && p.epsilonB == bytes16(0)) return (energy, force);
        bytes16 squared;
        for (uint256 k; k < 3; ++k) squared = m.add(squared, m.mul(displacement[k], displacement[k]));
        bytes16 distance = m.sqrt(squared);
        if (!direct && m.compare(distance, d.cutoff) >= 0) return (energy, force);
        if (p.sigmaA == p.sigmaB && p.epsilonA == p.epsilonB) {
            bytes16[3] memory zero; (energy, force) = LennardJonesKernel(modules.lj).evaluate(zero, displacement, p.sigmaA, p.epsilonA);
        } else {
            SoftcoreLennardJonesKernel.Configuration memory c = SoftcoreLennardJonesKernel.Configuration(
                SoftcoreLennardJonesKernel.Endpoint(p.sigmaA,p.epsilonA),SoftcoreLennardJonesKernel.Endpoint(p.sigmaB,p.epsilonB),r.lambda,d.softcoreAlpha);
            (energy, force,) = SoftcoreLennardJonesKernel(modules.softcore).evaluate(displacement, c);
        }
        if (!direct && m.compare(distance, d.switchDistance) > 0) {
            return _applySwitch(displacement,distance,d,energy,force);
        }
    }
    function _applySwitch(bytes16[3] memory displacement,bytes16 distance,AlchemicalTopologyCatalog.Definition memory d,bytes16 energy,bytes16[3] memory force)
        private view returns(bytes16,bytes16[3] memory)
    {
        FloatMath m=FloatMath(modules.math);
        (bytes16 switching,bytes16 derivative)=_switch(distance,d.switchDistance,d.cutoff);
        bytes16 correction=m.div(m.mul(energy,derivative),distance);
        force=_combineForce(force,displacement,switching,correction);
        return(m.mul(switching,energy),force);
    }
    function _combineForce(bytes16[3] memory force,bytes16[3] memory displacement,bytes16 scale,bytes16 correction)private view returns(bytes16[3] memory){
        FloatMath m=FloatMath(modules.math);for(uint256 k;k<3;++k)force[k]=m.add(m.mul(scale,force[k]),m.mul(correction,displacement[k]));return force;
    }
    function _switch(bytes16 distance, bytes16 rs, bytes16 rc) private view returns (bytes16 value, bytes16 derivative) {
        FloatMath m = FloatMath(modules.math); bytes16 width = m.sub(rc, rs);
        bytes16 x = m.div(m.sub(distance, rs), width); bytes16 t = m.div(m.sub(rc, distance), width); bytes16 t2 = m.mul(t, t);
        value = m.mul(m.mul(t2,t), m.add(m.sub(m.fromUInt(10),m.mul(m.fromUInt(15),t)),m.mul(m.fromUInt(6),t2)));
        derivative = m.neg(m.div(m.mul(m.fromUInt(30),m.mul(m.mul(x,x),t2)),width));
    }
    function _mixParticle(bytes32 stream, uint32 a, uint32 b) private view returns (bytes16 sigma, bytes16 epsilon) {
        FloatMath m = FloatMath(modules.math);
        sigma = m.div(m.add(_value(stream,uint64(a)*3),_value(stream,uint64(b)*3)),TWO);
        epsilon = m.sqrt(m.mul(_value(stream,uint64(a)*3+1),_value(stream,uint64(b)*3+1)));
    }
    function _exception(Run storage, AlchemicalTopologyCatalog.Definition memory d, uint64 index) private view returns (Pair memory p) {
        uint64 offset = index * 6; p.a = uint32(uint256(_word(d.a.exceptions,offset))); p.b = uint32(uint256(_word(d.a.exceptions,offset+1)));
        p.kind = uint32(uint256(_word(d.a.exceptions,offset+2))); p.sigmaA = _value(d.a.exceptions,offset+3); p.epsilonA = _value(d.a.exceptions,offset+4); p.desiredA = _value(d.a.exceptions,offset+5);
        p.sigmaB = _value(d.b.exceptions,offset+3); p.epsilonB = _value(d.b.exceptions,offset+4); p.desiredB = _value(d.b.exceptions,offset+5);
    }
    function _position(Run storage r, uint32 atom) private view returns (bytes16[3] memory p) {
        for (uint256 k; k < 3; ++k) p[k] = _decode(IProductionWordState(r.input.sourcePage).readWord(r.input.sourceNamespace,uint256(r.input.offset)+uint256(atom)*r.input.stride+k));
    }
    function _displacement(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 a, uint32 b) private view returns (bytes16[3] memory) {
        return OrthorhombicGeometry(modules.geometry).displacement(_position(r,a),_position(r,b),d.box);
    }
    function _bondedDisplacement(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 a, uint32 b) private view returns (bytes16[3] memory value) {
        value = _displacement(r,d,a,b); FloatMath m = FloatMath(modules.math);
        for (uint256 k; k < 3; ++k) if (m.compare(m.abs(value[k]),m.div(d.box[k],TWO)) == 0) revert InvalidInput();
    }
    function _charge(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 atom) private view returns (bytes16) {
        return _mix(_value(d.a.nonbonded,uint64(atom)*3+2),_value(d.b.nonbonded,uint64(atom)*3+2),r.lambda);
    }
    function _term(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint32 atom) private view returns (bytes16,bytes16) {
        return EwaldReciprocalKernel(modules.reciprocal).structureFactorTerm(_position(r,atom),_charge(r,d,atom),r.mode,d.box);
    }
    function _force(Run storage r, uint32 atom, bytes16[3] memory force, bool negative) private {
        if(((uint128(force[0])|uint128(force[1])|uint128(force[2]))&0x7fffffffffffffffffffffffffffffff)==0)return;
        FloatMath m = FloatMath(modules.math); bytes32[] memory words = new bytes32[](3);
        for (uint256 k; k < 3; ++k) { bytes16 old = _decode(outputPage.readWord(r.outputNamespace,uint256(atom)*3+k)); words[k] = _encode(negative ? m.sub(old,force[k]) : m.add(old,force[k])); }
        outputPage.writeWords(r.outputNamespace,uint256(atom)*3,words);
    }
    function _energy(Run storage r, AlchemicalTopologyCatalog.Definition memory d, uint256 component, bytes16 energy) private {
        if((uint128(energy)&0x7fffffffffffffffffffffffffffffff)==0)return;
        uint256 start = uint256(d.atoms)*3; FloatMath m = FloatMath(modules.math);
        outputPage.writeWord(r.outputNamespace,start,_encode(m.add(_decode(outputPage.readWord(r.outputNamespace,start)),energy)));
        outputPage.writeWord(r.outputNamespace,start+component+1,_encode(m.add(_decode(outputPage.readWord(r.outputNamespace,start+component+1)),energy)));
    }
    function _mix(bytes16 a, bytes16 b, bytes16 lambda) private view returns (bytes16) {
        if (a == b || lambda == bytes16(0)) return a; if (lambda == ONE) return b;
        FloatMath m = FloatMath(modules.math); return m.add(m.mul(m.sub(ONE,lambda),a),m.mul(lambda,b));
    }
    function _mixVector(bytes16[3] memory a, bytes16[3] memory b, bytes16 lambda) private view returns (bytes16[3] memory out) { for (uint256 k; k < 3; ++k) out[k] = _mix(a[k],b[k],lambda); }
    function _negative(bytes16[3] memory x) private view returns (bytes16[3] memory out) { for (uint256 k; k < 3; ++k) out[k] = FloatMath(modules.math).neg(x[k]); }
    function _word(bytes32 stream, uint64 index) private view returns (bytes32) { return AlchemicalTopologyCatalog(modules.topology).word(stream,index); }
    function _value(bytes32 stream, uint64 index) private view returns (bytes16) { return _decode(_word(stream,index)); }
    function _modeCount(uint32 extent) private pure returns (uint32) { uint32 width = extent*2+1; return extent*(1+width+width*width); }
    function _modeAt(uint32 index,uint32 extent) private pure returns (int32[3] memory mode) {
        uint32 width = extent*2+1;
        if(index<extent){mode[2]=int32(index+1);return mode;}index-=extent;
        if(index<extent*width){mode[1]=int32(index/width+1);mode[2]=int32(index%width)-int32(extent);return mode;}index-=extent*width;
        mode[0]=int32(index/(width*width)+1);mode[1]=int32((index/width)%width)-int32(extent);mode[2]=int32(index%width)-int32(extent);
    }
    function _pairIndices(uint64 index,uint32 count) private pure returns(uint32 a,uint32 b){
        uint256 low;uint256 high=count-1;while(low+1<high){uint256 mid=(low+high)/2;if(mid*(2*uint256(count)-mid-1)/2<=index)low=mid;else high=mid;}
        a=uint32(low);b=uint32(low+1+index-low*(2*uint256(count)-low-1)/2);
    }
    function _assertRun(Run storage r) private view {
        _dependencies(r.input.protocol);
        if (AlchemicalTopologyCatalog(modules.topology).assertTopology(r.input.topology) != r.topologyCommitment
            || r.input.sourcePage.codehash != r.sourceHash || r.sourceWriter.codehash != r.sourceWriterHash) revert DependencyChanged();
        (,bool frozen)=IProductionWordState(r.input.sourcePage).namespaceInfo(r.input.sourceNamespace);
        (,,,,bytes32 snapshot)=IProductionWordState(r.input.sourcePage).snapshotInfo(r.input.sourceNamespace);
        if(!frozen||snapshot!=r.snapshotCommitment)revert DependencyChanged();
    }
    function _dependencies(bytes32 protocol) private view returns (bytes32 manifest) {
        if(address(outputPage)==address(0))revert NotConfigured();address[12] memory addresses=_addresses(modules);
        ExperimentRegistry registry=ExperimentRegistry(modules.registry);manifest=registry.assertProtocol(protocol);
        for(uint256 i;i<12;++i){if(addresses[i].codehash!=moduleHashes[i])revert DependencyChanged();if(i!=0)registry.assertModule(protocol,addresses[i],moduleHashes[i]);}
        if(address(outputPage).codehash!=outputPageHash)revert DependencyChanged();registry.assertModule(protocol,address(outputPage),outputPageHash);registry.assertModule(protocol,address(this),address(this).codehash);
    }
    function _addresses(Modules memory m) private pure returns(address[12] memory){return[m.registry,m.topology,m.math,m.geometry,m.bond,m.angle,m.torsion,m.lj,m.softcore,m.realSpace,m.reciprocal,m.corrections];}
    function _get(uint256 id) private view returns(Run storage r){r=runs[id];if(r.stage==Stage.Missing)revert InvalidInput();}
    function _decode(bytes32 word) private pure returns(bytes16 value){if(uint256(word)>>128!=0)revert InvalidInput();value=bytes16(uint128(uint256(word)));if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();}
    function _encode(bytes16 value) private pure returns(bytes32){if(((uint128(value)>>112)&0x7fff)==0x7fff)revert InvalidInput();return bytes32(uint256(uint128(value)));}
}

contracts/core/BankedInputCatalog.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev One of the catalog's 96 permanent banks. Global indices are namespaced
///      by stream ID; neither another stream nor a later routing cycle aliases them.
contract InputWordBank {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidRange();

    address public immutable router;
    bytes32 public immutable routerCodeHash;
    uint8 public immutable bankIndex;
    mapping(bytes32 => mapping(uint64 => bytes32)) private _words;

    constructor(address router_, uint8 bankIndex_) {
        if (router_ != msg.sender || router_.code.length == 0 || bankIndex_ >= 96)
            revert InvalidConfiguration();
        router = router_;
        routerCodeHash = router_.codehash;
        bankIndex = bankIndex_;
    }

    function writeWords(bytes32 stream, uint64 start, bytes32[] calldata values) external {
        if (msg.sender != router || msg.sender.codehash != routerCodeHash) revert Unauthorized();
        _range(start, values.length);
        if (stream == bytes32(0)) revert InvalidRange();
        for (uint256 i; i < values.length; ++i) _words[stream][uint64(uint256(start) + i)] = values[i];
    }

    /// @dev Raw bank reads do not establish stream sealing or coverage. Consumers
    ///      must use the catalog's authenticated, sealed-stream read interface.
    function readWord(bytes32 stream, uint64 index) external view returns (bytes32) {
        _range(index, 1);
        return _words[stream][index];
    }

    function readWords(bytes32 stream, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        _range(start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) values[i] = _words[stream][uint64(uint256(start) + i)];
    }

    function _range(uint64 start, uint256 count) private view {
        if (count == 0 || count > 128 || uint256(start) + count - 1 > type(uint64).max
            || (uint256(start) / 4096) % 96 != bankIndex
            || count > 4096 - uint256(start) % 4096) revert InvalidRange();
    }
}

/// @notice Append-only input streams sharing exactly 96 permanent storage banks.
/// @dev Bank allocation is independent of model size and stream count. Storage
///      slots and gas still grow with words uploaded; 96 banks is not a size cap.
contract BankedInputCatalog {
    error Unauthorized();
    error InvalidConfiguration();
    error InvalidBankBatch();
    error BanksIncomplete();
    error BankChanged();
    error StreamExists();
    error UnknownStream();
    error StreamSealed();
    error IncompleteStream();
    error InvalidBatch();
    error InvalidRead();

    uint256 public constant BANK_COUNT = 96;
    uint256 public constant MAX_BANKS_PER_CREATION = 4;
    uint256 public constant PAGE_WORDS = 4096;
    uint256 public constant MAX_BATCH_WORDS = 128;
    address public immutable owner;
    uint8 public bankCount;
    bytes32 public banksCommitment;

    struct Bank { address instance; bytes32 codeHash; }
    struct Stream {
        bytes32 role;
        uint64 totalWords;
        uint64 appendedWords;
        bool isSealed;
        bool exists;
        bytes32 rollingDigest;
        bytes32 commitment;
    }
    Bank[96] private _banks;
    mapping(bytes32 => Stream) private _streams;

    event BankCreated(uint8 indexed bankIndex, address indexed instance, bytes32 codeHash);
    event BanksReady(bytes32 commitment);
    event StreamBegun(bytes32 indexed stream, bytes32 indexed role, uint64 totalWords);
    event WordsAppended(bytes32 indexed stream, uint64 start, uint32 count, bytes32 rollingDigest);
    event StreamFrozen(bytes32 indexed stream, bytes32 commitment, uint64 totalWords);

    modifier onlyOwner() { if (msg.sender != owner) revert Unauthorized(); _; }

    constructor(address owner_) {
        if (owner_ == address(0)) revert InvalidConfiguration();
        owner = owner_;
        banksCommitment = keccak256(abi.encode(bytes32("ORVIA-INPUT-BANKS-v1"),
            block.chainid, address(this), BANK_COUNT, PAGE_WORDS));
    }

    /// @notice Allocate the next 1–4 banks. No other function creates contracts.
    function createBanks(uint8 count) external onlyOwner {
        if (count == 0 || count > MAX_BANKS_PER_CREATION || uint256(bankCount) + count > BANK_COUNT)
            revert InvalidBankBatch();
        for (uint256 i; i < count; ++i) {
            uint8 index = bankCount;
            address instance = address(new InputWordBank{salt: bytes32(uint256(index))}(address(this), index));
            bytes32 codeHash = instance.codehash;
            _banks[index] = Bank(instance, codeHash);
            banksCommitment = keccak256(abi.encode(banksCommitment, index, instance, codeHash));
            ++bankCount;
            emit BankCreated(index, instance, codeHash);
        }
        if (bankCount == BANK_COUNT) emit BanksReady(banksCommitment);
    }

    function bankInfo(uint8 index) external view returns (address instance, bytes32 codeHash) {
        if (index >= BANK_COUNT) revert InvalidRead();
        Bank storage bank = _banks[index];
        return (bank.instance, bank.codeHash);
    }

    function bankForWord(uint64 index) public pure returns (uint8) {
        return uint8((uint256(index) / PAGE_WORDS) % BANK_COUNT);
    }

    function beginStream(bytes32 id, bytes32 role, uint64 totalWords) external onlyOwner {
        if (bankCount != BANK_COUNT) revert BanksIncomplete();
        if (id == bytes32(0) || role == bytes32(0)) revert InvalidConfiguration();
        if (_streams[id].exists) revert StreamExists();
        Stream storage stream = _streams[id];
        stream.role = role;
        stream.totalWords = totalWords;
        stream.exists = true;
        stream.rollingDigest = keccak256(abi.encode(bytes32("ORVIA-BANKED-INPUT-v1"),
            block.chainid, address(this), id, role, totalWords, banksCommitment));
        emit StreamBegun(id, role, totalWords);
    }

    /// @notice Append the next canonical words, without caller-selected offsets.
    function appendWords(bytes32 id, bytes32[] calldata values) external onlyOwner {
        Stream storage stream = _get(id);
        if (stream.isSealed) revert StreamSealed();
        uint256 count = values.length;
        if (count == 0 || count > MAX_BATCH_WORDS || count > stream.totalWords - stream.appendedWords)
            revert InvalidBatch();
        uint64 start = stream.appendedWords;
        bytes32 digest = stream.rollingDigest;
        uint256 done;
        while (done < count) {
            uint64 index = uint64(uint256(start) + done);
            uint256 length = count - done;
            uint256 remainder = PAGE_WORDS - uint256(index) % PAGE_WORDS;
            if (length > remainder) length = remainder;
            Bank storage bank = _bank(bankForWord(index));
            InputWordBank(bank.instance).writeWords(id, index, values[done:done + length]);
            for (uint256 i; i < length; ++i)
                digest = keccak256(abi.encode(digest, uint64(uint256(index) + i), values[done + i]));
            done += length;
        }
        stream.appendedWords += uint64(count);
        stream.rollingDigest = digest;
        emit WordsAppended(id, start, uint32(count), digest);
    }

    function sealStream(bytes32 id) external onlyOwner returns (bytes32 commitment) {
        Stream storage stream = _get(id);
        if (stream.isSealed) revert StreamSealed();
        if (stream.appendedWords != stream.totalWords) revert IncompleteStream();
        commitment = keccak256(abi.encode(bytes32("ORVIA-SEALED-BANKS-v1"), block.chainid,
            address(this), id, stream.role, stream.totalWords, stream.rollingDigest, banksCommitment));
        stream.commitment = commitment;
        stream.isSealed = true;
        emit StreamFrozen(id, commitment, stream.totalWords);
    }

    function assertStream(bytes32 id) external view returns (bytes32 commitment, uint64 wordCount) {
        Stream storage stream = _sealed(id);
        return (stream.commitment, stream.totalWords);
    }

    function readWord(bytes32 id, uint64 index) external view returns (bytes32) {
        Stream storage stream = _sealed(id);
        if (index >= stream.totalWords) revert InvalidRead();
        return InputWordBank(_bank(bankForWord(index)).instance).readWord(id, index);
    }

    function readWords(bytes32 id, uint64 start, uint32 count) external view returns (bytes32[] memory values) {
        Stream storage stream = _sealed(id);
        if (count > MAX_BATCH_WORDS || start > stream.totalWords || count > stream.totalWords - start)
            revert InvalidRead();
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint64 index = uint64(uint256(start) + done);
            uint256 length = count - done;
            uint256 remainder = PAGE_WORDS - uint256(index) % PAGE_WORDS;
            if (length > remainder) length = remainder;
            bytes32[] memory words = InputWordBank(_bank(bankForWord(index)).instance)
                .readWords(id, index, uint32(length));
            for (uint256 i; i < length; ++i) values[done + i] = words[i];
            done += length;
        }
    }

    /// @dev ABI-compatible with PartitionedInputCatalog. pageCount is the logical
    ///      4096-word block count, never a count of additional deployed contracts.
    function streamInfo(bytes32 id) external view returns (
        bytes32 role, uint64 totalWords, uint64 appendedWords, uint64 pageCount, bool isSealed, bytes32 commitment
    ) {
        Stream storage stream = _get(id);
        return (stream.role, stream.totalWords, stream.appendedWords,
            uint64((uint256(stream.appendedWords) + PAGE_WORDS - 1) / PAGE_WORDS), stream.isSealed, stream.commitment);
    }

    function _bank(uint8 index) private view returns (Bank storage bank) {
        bank = _banks[index];
        if (bank.instance.code.length == 0 || bank.instance.codehash != bank.codeHash) revert BankChanged();
    }
    function _get(bytes32 id) private view returns (Stream storage stream) {
        stream = _streams[id];
        if (!stream.exists) revert UnknownStream();
    }
    function _sealed(bytes32 id) private view returns (Stream storage stream) {
        stream = _get(id);
        if (!stream.isSealed) revert IncompleteStream();
    }
}

contracts/core/BankedWorkingState.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @dev One member of a fixed, router-created pool. Namespace and GLOBAL word
///      index remain in the key when different logical pages reuse this bank.
contract BankedStateStorageBank {
    error Unauthorized();
    error InvalidRange();
    error InvalidEpoch();

    address public immutable router;
    bytes32 public immutable routerCodeHash;
    struct Version { uint64 epoch; bytes32 value; }
    mapping(bytes32 => mapping(uint256 => Version[])) private _history;

    constructor(address router_) {
        if (router_ != msg.sender || router_.code.length == 0) revert Unauthorized();
        router = router_; routerCodeHash = router_.codehash;
    }

    modifier onlyRouter() {
        if (msg.sender != router || router.codehash != routerCodeHash) revert Unauthorized();
        _;
    }

    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values, uint64 epoch)
        external onlyRouter
    {
        if (epoch == 0) revert InvalidEpoch();
        _range(start, values.length);
        if (values.length == 0) revert InvalidRange();
        for (uint256 i; i < values.length; ++i) {
            Version[] storage versions = _history[namespace][start + i];
            uint256 length = versions.length;
            if (length != 0 && versions[length - 1].epoch > epoch) revert InvalidEpoch();
            if (length != 0 && versions[length - 1].epoch == epoch) versions[length - 1].value = values[i];
            else versions.push(Version(epoch, values[i]));
        }
    }

    function readWords(bytes32 namespace, uint256 start, uint256 count, uint64 epoch)
        external view onlyRouter returns (bytes32[] memory values)
    {
        if (epoch == 0) revert InvalidEpoch();
        _range(start, count);
        values = new bytes32[](count);
        for (uint256 i; i < count; ++i) {
            Version[] storage versions = _history[namespace][start + i];
            uint256 low; uint256 high = versions.length;
            if (high == 0) continue;
            if (versions[high - 1].epoch <= epoch) { values[i] = versions[high - 1].value; continue; }
            // At most one version per strictly increasing uint64 epoch: <=64
            // predecessor-search rounds, independent of namespaces/page count.
            while (low < high) {
                uint256 middle = low + (high - low) / 2;
                if (versions[middle].epoch <= epoch) low = middle + 1;
                else high = middle;
            }
            if (low != 0) values[i] = versions[low - 1].value;
        }
    }

    function _range(uint256 start, uint256 count) private pure {
        if (start >= type(uint32).max || count > 128 || count > 4096 - (start % 4096)
            || count > uint256(type(uint32).max) - start) revert InvalidRange();
    }
}

/// @notice Mutable word namespaces and retained snapshots in a fixed bank pool.
/// @dev Matches the ShardedWorkingState consumer ABI. Provisioning is explicit:
///      reads of unprovisioned, unwritten banks are zero; writes fail closed.
///      No namespace, write, snapshot or seal operation deploys a child contract.
contract BankedWorkingState {
    error Unauthorized();
    error InvalidWriter();
    error InvalidBankCount();
    error InvalidNamespace();
    error NamespaceExists();
    error UnknownNamespace();
    error InvalidCapacity();
    error NamespaceSealed();
    error InvalidBatch();
    error OutOfBounds();
    error InvalidSnapshotSource();
    error NotSnapshot();
    error EpochExhausted();
    error BankUnavailable();
    error BankChanged();

    uint256 public constant MAX_CAPACITY_WORDS = type(uint32).max;
    uint256 public constant MAX_BATCH_WORDS = 128;
    uint256 public constant SHARD_WORDS = 4096;
    uint256 public constant MAX_BANKS = 128;
    uint256 public constant MAX_BANKS_PER_DEPLOY = 4;
    address public immutable writer;
    bytes32 public immutable writerCodeHash;
    uint16 public immutable bankCount;
    uint16 public deployedBankCount;
    bytes32 public bankRuntimeCodeHash;

    struct Bank { address page; bytes32 codeHash; }
    struct Namespace {
        uint32 capacityWords;
        bool isSealed;
        bool isSnapshot;
        uint64 epoch;
        bytes32 source;
        bytes32 writeDigest;
        bytes32 commitment;
    }
    mapping(uint256 => Bank) private _banks;
    mapping(bytes32 => Namespace) private _namespaces;

    event BankDeployed(uint256 indexed index, address indexed page, bytes32 codeHash);
    event NamespaceCreated(bytes32 indexed namespace, uint32 capacityWords);
    event WordsWritten(bytes32 indexed namespace, uint256 start, uint256 count, bytes32 writeDigest);
    event NamespaceFrozen(bytes32 indexed namespace);
    event SnapshotCreated(bytes32 indexed source, bytes32 indexed snapshot, uint64 epoch, bytes32 commitment);

    modifier onlyWriter() {
        if (msg.sender != writer || writer.codehash != writerCodeHash) revert Unauthorized();
        _;
    }

    constructor(address writer_, uint16 bankCount_) {
        if (writer_ == address(0) || writer_.code.length == 0) revert InvalidWriter();
        if (bankCount_ == 0 || bankCount_ > MAX_BANKS) revert InvalidBankCount();
        writer = writer_; writerCodeHash = writer_.codehash; bankCount = bankCount_;
    }

    /// @notice Anyone may pay to provision the next <=4 predetermined banks.
    /// @dev Cannot register arbitrary code, replace a bank or grow the fixed pool.
    function deployBanks(uint256 work) external returns (uint256 processed, bool complete) {
        if (work == 0 || work > MAX_BANKS_PER_DEPLOY) revert InvalidBatch();
        uint256 next = deployedBankCount;
        while (processed < work && next < bankCount) {
            address page = address(new BankedStateStorageBank{salt: bytes32(next)}(address(this)));
            bytes32 codeHash = page.codehash;
            if (next == 0) bankRuntimeCodeHash = codeHash;
            else if (codeHash != bankRuntimeCodeHash) revert BankChanged();
            _banks[next] = Bank(page, codeHash);
            emit BankDeployed(next, page, codeHash);
            ++next; ++processed;
        }
        deployedBankCount = uint16(next);
        complete = next == bankCount;
    }

    function createNamespace(bytes32 namespace, uint32 capacityWords) external onlyWriter {
        if (namespace == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[namespace].capacityWords != 0) revert NamespaceExists();
        if (capacityWords == 0) revert InvalidCapacity();
        Namespace storage n = _namespaces[namespace];
        n.capacityWords = capacityWords; n.epoch = 1;
        n.writeDigest = keccak256(abi.encode(bytes32("ORVIA-BANKED-STATE-v1"), block.chainid,
            address(this), writer, writerCodeHash, bankCount, namespace, capacityWords));
        emit NamespaceCreated(namespace, capacityWords);
    }

    function writeWord(bytes32 namespace, uint256 index, bytes32 value) external onlyWriter {
        bytes32[] memory values = new bytes32[](1); values[0] = value;
        _write(namespace, index, values);
    }
    function writeWords(bytes32 namespace, uint256 start, bytes32[] calldata values) external onlyWriter {
        _write(namespace, start, values);
    }
    function _write(bytes32 namespace, uint256 start, bytes32[] memory values) private {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        if (values.length == 0 || values.length > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(n.capacityWords, start, values.length);
        uint256 done;
        while (done < values.length) {
            uint256 index = start + done;
            uint256 count = values.length - done;
            if (count > SHARD_WORDS - (index % SHARD_WORDS)) count = SHARD_WORDS - (index % SHARD_WORDS);
            Bank storage bank = _banks[(index / SHARD_WORDS) % bankCount];
            if (bank.page == address(0)) revert BankUnavailable();
            _assertBank(bank);
            bytes32[] memory chunk = new bytes32[](count);
            for (uint256 i; i < count; ++i) {
                chunk[i] = values[done + i];
                n.writeDigest = keccak256(abi.encode(n.writeDigest, index + i, chunk[i]));
            }
            BankedStateStorageBank(bank.page).writeWords(namespace, index, chunk, n.epoch);
            done += count;
        }
        emit WordsWritten(namespace, start, values.length, n.writeDigest);
    }

    function readWord(bytes32 namespace, uint256 index) external view returns (bytes32) {
        return _read(namespace, index, 1)[0];
    }
    function readWords(bytes32 namespace, uint256 start, uint256 count) external view returns (bytes32[] memory) {
        return _read(namespace, start, count);
    }
    function _read(bytes32 namespace, uint256 start, uint256 count) private view returns (bytes32[] memory values) {
        Namespace storage viewNamespace = _get(namespace);
        if (count > MAX_BATCH_WORDS) revert InvalidBatch();
        _range(viewNamespace.capacityWords, start, count);
        bytes32 source = viewNamespace.isSnapshot ? viewNamespace.source : namespace;
        uint64 epoch = viewNamespace.isSnapshot ? viewNamespace.epoch : _namespaces[source].epoch;
        values = new bytes32[](count);
        uint256 done;
        while (done < count) {
            uint256 index = start + done;
            uint256 length = count - done;
            if (length > SHARD_WORDS - (index % SHARD_WORDS)) length = SHARD_WORDS - (index % SHARD_WORDS);
            Bank storage bank = _banks[(index / SHARD_WORDS) % bankCount];
            if (bank.page != address(0)) {
                _assertBank(bank);
                bytes32[] memory chunk = BankedStateStorageBank(bank.page).readWords(source, index, length, epoch);
                for (uint256 i; i < length; ++i) values[done + i] = chunk[i];
            }
            done += length;
        }
    }

    /// @dev Only the pinned writer establishes scientific completion and derives
    ///      snapshot names from complete run/step identity. Storage does not infer it.
    function snapshotNamespace(bytes32 source, bytes32 snapshot) external onlyWriter returns (bytes32 commitment) {
        Namespace storage n = _get(source);
        if (n.isSnapshot) revert InvalidSnapshotSource();
        if (snapshot == bytes32(0)) revert InvalidNamespace();
        if (_namespaces[snapshot].capacityWords != 0) revert NamespaceExists();
        if (n.epoch == type(uint64).max) revert EpochExhausted();
        Namespace storage s = _namespaces[snapshot];
        s.capacityWords = n.capacityWords; s.isSealed = true; s.isSnapshot = true;
        s.epoch = n.epoch; s.source = source; s.writeDigest = n.writeDigest;
        commitment = keccak256(abi.encode(bytes32("ORVIA-BANKED-SNAPSHOT-v1"), block.chainid,
            address(this), writer, writerCodeHash, bankCount, source, snapshot, s.epoch, s.capacityWords, s.writeDigest));
        s.commitment = commitment; ++n.epoch;
        emit SnapshotCreated(source, snapshot, s.epoch, commitment);
    }
    function snapshotInfo(bytes32 snapshot) external view returns (
        bytes32 source, uint64 epoch, uint32 capacityWords, bytes32 writeDigest, bytes32 commitment
    ) {
        Namespace storage s = _get(snapshot);
        if (!s.isSnapshot) revert NotSnapshot();
        return (s.source, s.epoch, s.capacityWords, s.writeDigest, s.commitment);
    }
    function namespaceInfo(bytes32 namespace) external view returns (uint32 capacityWords, bool isSealed) {
        Namespace storage n = _get(namespace); return (n.capacityWords, n.isSealed);
    }
    function namespaceCommitment(bytes32 namespace) external view returns (bytes32 writeDigest, uint64 epoch) {
        Namespace storage n = _get(namespace); return (n.writeDigest, n.epoch);
    }
    function bankInfo(uint256 index) external view returns (address page, bytes32 codeHash) {
        if (index >= bankCount) revert OutOfBounds();
        Bank storage bank = _banks[index]; return (bank.page, bank.codeHash);
    }
    /// @notice Compatibility metadata: logical pages share physical bank addresses.
    function shardInfo(bytes32 namespace, uint256 shardIndex) external view returns (address page, bytes32 codeHash) {
        Namespace storage n = _get(namespace);
        if (shardIndex >= (uint256(n.capacityWords) + SHARD_WORDS - 1) / SHARD_WORDS) revert OutOfBounds();
        Bank storage bank = _banks[shardIndex % bankCount]; return (bank.page, bank.codeHash);
    }
    function sealNamespace(bytes32 namespace) external onlyWriter {
        Namespace storage n = _get(namespace);
        if (n.isSealed) revert NamespaceSealed();
        n.isSealed = true; emit NamespaceFrozen(namespace);
    }
    function _assertBank(Bank storage bank) private view {
        if (bank.page.code.length == 0 || bank.page.codehash != bank.codeHash
            || bank.codeHash != bankRuntimeCodeHash) revert BankChanged();
    }
    function _get(bytes32 namespace) private view returns (Namespace storage n) {
        n = _namespaces[namespace]; if (n.capacityWords == 0) revert UnknownNamespace();
    }
    function _range(uint32 capacity, uint256 start, uint256 count) private pure {
        if (start > capacity || count > uint256(capacity) - start) revert OutOfBounds();
    }
}

